# Drop duplicate Copy link already in list — generator de-dupes.


def _row(tr, es, fr, de, pt, it, ru, ar, zh, zht, ja, ko, hi, vi, th, idn, pl, uk, nl, fa, he, sgn) -> dict[str, str]:
    return {
        "tr": tr, "es": es, "fr": fr, "de": de, "pt": pt, "it": it, "ru": ru, "ar": ar,
        "zh-Hans": zh, "zh-Hant": zht, "ja": ja, "ko": ko, "hi": hi, "vi": vi, "th": th,
        "id": idn, "pl": pl, "uk": uk, "nl": nl, "fa": fa, "he": he, "sgn": sgn,
    }


EXTRA_OVR: dict[str, dict[str, str]] = {}


def _en_nl(nl: str, en: str | None = None) -> dict[str, str]:
    e = en if en is not None else nl
    return _row(e, e, e, e, e, e, e, e, e, e, e, e, e, e, e, e, e, e, nl, e, e, e)


def _put(key: str, row: dict[str, str]) -> None:
    for code, val in row.items():
        EXTRA_OVR.setdefault(code, {})[key] = val


